    event.vehicle = sVehicle;
    b->events[b->head] = event;
    b->head = (b->head + 1) % P4_TWAI_TX_LIFECYCLE_CAPACITY;
    if (b->count < P4_TWAI_TX_LIFECYCLE_CAPACITY) ++b->count;
    else if (b->overwritten != UINT32_MAX) ++b->overwritten;
    ++sRevision;
}

